import pandas as pd
import numpy as np
import statsmodels.api as sm

class CR001Scorecard:
    """CR-001 Retail PD Scorecard translated from R."""
    def __init__(self):
        self.woe_tabs = {}
        self.G = None
        self.B = None
        self.model = None

    # ----- binning helpers (quirk: amount missing -> 0, right‑closed = False) -----
    @staticmethod
    def _bin_duration(x):
        bins = [-np.inf, 12, 24, 36, np.inf]
        labels = ["lt12", "12-24", "24-36", "36+"]
        return pd.cut(x, bins=bins, right=False, labels=labels).astype(str)

    @staticmethod
    def _bin_amount(x):
        x = x.copy()
        x = x.fillna(0)  # missing amount = 0 (quirk from original script)
        bins = [-np.inf, 1400, 4000, 8000, np.inf]
        labels = ["lt1400", "1400-4000", "4000-8000", "8000+"]
        return pd.cut(x, bins=bins, right=False, labels=labels).astype(str)

    def _make_bins(self, df):
        return pd.DataFrame({
            "checking": df["status.of.existing.checking.account"].astype(str),
            "duration": self._bin_duration(df["duration.in.month"]),
            "history": df["credit.history"].astype(str),
            "purpose": df["purpose"].astype(str),
            "amount": self._bin_amount(df["credit.amount"]),
            "savings": df["savings.account.and.bonds"].astype(str),
            "employment": df["present.employment.since"].astype(str),
            "instalment": df["installment.rate.in.percentage.of.disposable.income"].astype(str)
        })

    # ----- WoE calculation (quirk: +0.5 smoothing) -----
    def _calc_woe(self, bins, bad):
        self.G = (bad == 0).sum()
        self.B = (bad == 1).sum()
        self.woe_tabs = {}
        for col in bins.columns:
            lv = bins[col].unique()
            ng = bins[col].map(lambda v: ((bad == 0) & (bins[col] == v)).sum())
            nb = bins[col].map(lambda v: ((bad == 1) & (bins[col] == v)).sum())
            woe_vals = np.log(((nb + 0.5) / self.B) / ((ng + 0.5) / self.G))
            tab = pd.DataFrame({
                "var": col,
                "bin": lv,
                "n_good": ng,
                "n_bad": nb,
                "woe": woe_vals
            })
            self.woe_tabs[col] = tab

    def _apply_woe(self, bins):
        woe_df = pd.DataFrame(index=bins.index)
        for col in bins.columns:
            tab = self.woe_tabs[col][["bin", "woe"]].set_index("bin")
            woe_df[f"woe_{col}"] = bins[col].map(tab["woe"])
        return woe_df

    def fit(self, df):
        """Fit the scorecard on a training dataframe."""
        bad = (df["creditability"] == "bad").astype(int)
        bins = self._make_bins(df)
        self._calc_woe(bins, bad)
        X = self._apply_woe(bins)
        X = sm.add_constant(X, has_constant='add')
        self.model = sm.GLM(bad, X, family=sm.families.Binomial()).fit()
        return self

    def predict_pd(self, df):
        """Return probability of default (PD) for each row."""
        bins = self._make_bins(df)
        X = self._apply_woe(bins)
        X = sm.add_constant(X, has_constant='add')
        return self.model.predict(X)

    def score(self, df):
        """Return DataFrame with pd, points and decision."""
        pd_series = self.predict_pd(df)
        points = np.round(600 + (50 / np.log(2)) * np.log((1 - pd_series) / pd_series)).astype(int)
        decision = np.where(pd_series > 0.35, "DECLINE", "APPROVE")  # quirk: comment says 0.25 but code uses 0.35
        return pd.DataFrame({"pd": pd_series, "points": points, "decision": decision}, index=df.index)

    def woe_features(self, df):
        """Return only the WoE transformed features."""
        bins = self._make_bins(df)
        return self._apply_woe(bins)

    def woe_table(self):
        """Concatenate all per‑variable WoE tables."""
        return pd.concat(self.woe_tabs.values(), ignore_index=True)

    @property
    def coef(self):
        """Model coefficients (including intercept)."""
        return self.model.params if self.model is not None else None
